package com.taylordproductivty.med_timing_tracker.notifications

import android.content.Context
import androidx.work.CoroutineWorker
import androidx.work.WorkerParameters

class CoarseReminderWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        val doseLogId = inputData.getInt(ExactAlarmScheduler.EXTRA_DOSE_LOG_ID, -1)
        if (doseLogId == -1) return Result.failure()
        val title = inputData.getString(ExactAlarmScheduler.EXTRA_TITLE) ?: return Result.failure()
        val text = inputData.getString(ExactAlarmScheduler.EXTRA_TEXT) ?: return Result.failure()
        NotificationHelper.sendReminder(applicationContext, doseLogId, title, text)
        return Result.success()
    }
}
